"""Power BI Desktop answers (saved in tools/parity/dax_battery_{earlier_arith,boolean_scalar_rhs,filter_transition,boolean_filter_functions,sdet_filters,comments_booleans}.json)
replayed through the app's evaluator: EARLIER in arithmetic, scalar tables in a Boolean CALCULATE filter, CALCULATETABLE in FILTER rows, comments, Booleans in iterators."""

import unittest

from tools import dax_oracle_diff as dax
from tools.parity_check import status


class BooleanFilterScalarTests(unittest.TestCase):
    def check(self, cases):
        for expression, powerbi in cases:
            with self.subTest(expression=expression):
                self.assertEqual(status(powerbi, dax.local(expression)), "match", (powerbi, dax.local(expression)))

    def test_original_nine_refusals_matches_power_bi(self):
        self.check([
        ('SUMX(Facts,CALCULATE(COUNTROWS(Facts),Facts[Quantity]*2>EARLIER(Facts[Quantity])*3))', 'BLANK'),
        ('CALCULATE(COUNTROWS(Facts),Facts[Quantity]>COUNTROWS(CALCULATETABLE(Facts,Facts[Region]="East")))', '2'),
        ('CALCULATE(COUNTROWS(Facts),Facts[Quantity]>COUNTROWS(VALUES(Facts[Region])))', '2'),
        ('CALCULATE(COUNTROWS(Facts),Facts[Quantity]>SUMX(FILTER(Facts,Facts[Region]="East"),1))', '2'),
        ('MAXX(VALUES(Facts[Region]),CALCULATE(COUNTROWS(VALUES(Facts[Note]))))', '2'),
        ('MAXX(VALUES(Facts[Region]),CALCULATE(COUNTROWS(VALUES(Facts[Note])),Facts[Quantity]>1))', '2'),
        ('SUMX(Facts,COUNTROWS(FILTER(Facts,Facts[Quantity]>EARLIER(Facts[Quantity])*1)))', '15'),
        ('SUMX(VALUES(Facts[Quantity]),COUNTROWS(FILTER(Facts,Facts[Quantity]>EARLIER(Facts[Quantity])*1)))', '15'),
        ('SUMX(ALL(Facts[Quantity]),COUNTROWS(FILTER(Facts,Facts[Quantity]>EARLIER(Facts[Quantity])*1)))', '15'),
        ])

