        ('CONCATENATEX(Facts,IF(Facts[Quantity]>1,SWITCH(Facts[Quantity],2,TRUE(),3,Facts[Quantity]>2)),"|",Facts[Quantity])', 'FALSE|FALSE|TRUE|TRUE|FALSE|FALSE'),
